use std::fmt::Write;

use cs2metal_elf::ObjectType;

use crate::{Demand, Inventory};

/// Renders an inventory as Markdown. The scanned root is shown as `<game_dir>` so
/// that a report never carries a machine-specific path.
pub fn markdown(inventory: &Inventory) -> String {
    let mut out = String::new();
    let w = &mut out;
    let executables = inventory
        .modules
        .iter()
        .filter(|m| m.object_type == ObjectType::Executable || m.pie)
        .count();

    line(w, "# CS2 Linux build inventory");
    line(w, "");
    line(
        w,
        "Generated by `cs2metal inventory` from local game files. It is derived from \
         Valve's binaries: keep it in `reports/` and never commit it.",
    );
    line(w, "");
    line(w, "## Summary");
    line(w, "");
    line(w, "| Measure | Value |");
    line(w, "| --- | --- |");
    row(w, "ELF modules", inventory.modules.len());
    row(w, "Executables (fixed or PIE)", executables);
    row(w, "Unparsable ELF files", inventory.skipped.len());
    row(w, "Host libraries required", inventory.host_libraries.len());
    row(
        w,
        "Host symbols required (non-weak)",
        inventory.required_symbol_count(),
    );
    row(
        w,
        "Imports interposed by bundled modules",
        inventory.interposed.len(),
    );
    row(
        w,
        "Modules with TLS",
        inventory.modules.iter().filter(|m| m.uses_tls).count(),
    );
    row(
        w,
        "Modules with text relocations",
        inventory
            .modules
            .iter()
            .filter(|m| m.text_relocations)
            .count(),
    );
    let interpreters: Vec<_> = inventory
        .interpreters
        .iter()
        .map(|i| format!("`{i}`"))
        .collect();
    row(w, "Interpreters", interpreters.join(", "));
    line(w, "");

    line(w, "## Host libraries");
    line(w, "");
    line(w, "| Library | Family | Symbols | Required by |");
    line(w, "| --- | --- | --- | --- |");
    for lib in &inventory.host_libraries {
        let _ = writeln!(
            w,
            "| `{}` | {} | {} | {} |",
            lib.name,
            lib.family.label(),
            lib.symbols.len(),
            lib.required_by.len()
        );
    }
    line(w, "");

    for lib in &inventory.host_libraries {
        if lib.symbols.is_empty() {
            continue;
        }
        let _ = writeln!(w, "### `{}`", lib.name);
        line(w, "");
        symbol_table(w, lib.symbols.iter());
    }

    if !inventory.unattributed.is_empty() {
        line(w, "## Unversioned imports no bundled module provides");
        line(w, "");
        symbol_table(w, inventory.unattributed.iter());
    }

    if !inventory.interposed.is_empty() {
        line(w, "## Host imports interposed by bundled modules");
        line(w, "");
        line(w, "| Symbol | Bundled definition |");
        line(w, "| --- | --- |");
        for (symbol, module) in &inventory.interposed {
            let _ = writeln!(w, "| `{symbol}` | `{module}` |");
        }
        line(w, "");
    }

    line(w, "## Relocations");
    line(w, "");
    line(w, "| Type | Count |");
    line(w, "| --- | --- |");
    for (kind, count) in &inventory.relocations {
        let _ = writeln!(w, "| `{kind}` | {count} |");
    }
    line(w, "");

    line(w, "## Modules");
    line(w, "");
    line(
        w,
        "| Path | Type | Machine | Needed (host) | Imports | Exports | TLS | COPY |",
    );
    line(w, "| --- | --- | --- | --- | --- | --- | --- | --- |");
    for m in &inventory.modules {
        let kind = match (m.object_type, m.pie) {
            (ObjectType::Executable, _) => "exec",
            (ObjectType::SharedObject, true) => "pie",
            (ObjectType::SharedObject, false) => "shared",
            _ => "other",
        };
        let host_needed = m.needed.iter().filter(|n| n.bundled.is_none()).count();
        let _ = writeln!(
            w,
            "| `{}` | {kind} | {} | {} ({host_needed}) | {} | {} | {} | {} |",
            m.path,
            m.machine,
            m.needed.len(),
            m.imports,
            m.exports,
            if m.static_tls {
                "static"
            } else if m.uses_tls {
                "yes"
            } else {
                ""
            },
            m.copy_relocations.len()
        );
    }

    if !inventory.skipped.is_empty() {
        line(w, "");
        line(w, "## Skipped files");
        line(w, "");
        for s in &inventory.skipped {
            let _ = writeln!(w, "- `{}`: {}", s.path, s.reason);
        }
    }
    out
}

fn line(w: &mut String, text: &str) {
    w.push_str(text);
    w.push('\n');
}

fn row(w: &mut String, name: &str, value: impl std::fmt::Display) {
    let _ = writeln!(w, "| {name} | {value} |");
}

fn symbol_table<'a>(w: &mut String, symbols: impl Iterator<Item = (&'a String, &'a Demand)>) {
    line(w, "| Symbol | Versions | Weak only | Modules |");
    line(w, "| --- | --- | --- | --- |");
    for (name, demand) in symbols {
        let versions: Vec<_> = demand.versions.iter().map(String::as_str).collect();
        let _ = writeln!(
            w,
            "| `{name}` | {} | {} | {} |",
            versions.join(", "),
            if demand.weak_only { "yes" } else { "" },
            demand.referenced_by.len()
        );
    }
    line(w, "");
}
